SourceCode.Declaration:
/// <summary>
/// TDD CB871_CB872 Sales returns. Caculates WMS factor for return order line and unit in ship case
/// </summary>
internal class METCalcWMSFactor
{
}

Method.Source:
/// <summary>
/// Constructs and returns <c>METCalcWMSFactor</c> object.
/// </summary>
/// <returns> <c>METCalcWMSFactor</c> object. </returns>
public static METCalcWMSFactor construct()
{
    METCalcWMSFactor calcWMSFactor = new METCalcWMSFactor();

    return calcWMSFactor;
}

/// <summary>
/// Get Purchase WMS unit conversion factor for return order sales line
/// </summary>
/// <param name = "_fromUnit">From unit for conversion factor</param>
/// <param name = "_itemId">Item id for conversion factor calculation</param>
/// <param name = "_inventDimId">Invent dim id for conversion factor calculation</param>
/// <param name = "_toUnit">To unit for conversion factor</param>
/// <returns>Returns calculated conversion factor</returns>
private METPurchaseWMSFactor getConversionFactor(UnitOfMeasureSymbol _fromUnit, ItemId _itemId, InventDimId _inventDimId, UnitOfMeasureSymbol _toUnit)
{
    METPurchaseWMSFactor    conversionFactor;

    if (_toUnit == _fromUnit)
    {
        conversionFactor = 1;
    }
    else
    {
        conversionFactor = EcoResProductUnitConverter::convertForReleasedProduct(
                    _itemId,
                    _inventDimId,
                    1,
                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_fromUnit),
                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_toUnit),
                    NoYes::No,
                    NoYes::No);

    }
    return conversionFactor;
}

/// <summary>
/// Get WMS factor for return order line
/// </summary>
/// <param name = "_salesLine">Return order sales line</param>
/// <returns>Returns wms factor for return order line</returns>
public METPurchaseWMSFactor getPurchaseWMSFactorForReturnLine(SalesLine _salesLine)
{
    METPurchaseWMSFactor metPurchaseWMSFactor;

    if (_salesLine.ExpectedRetQty < 0)
    {
        UnitOfMeasureSymbol  defaultUnit;
        METInventLocation    inventLocation = METInventLocation::findByInventLocationId(_salesLine.inventDim().InventLocationId);

        switch (inventLocation.ExternalWMSUnit)
        {
            case METExtWMSUnit::DefaultInventoryUnit:
                defaultUnit     = InventTable::find(_salesLine.ItemId).inventTableModuleInvent().UnitId;
                break;
            case METExtWMSUnit::DefaultSellUnit:
                defaultUnit     = InventTable::find(_salesLine.ItemId).inventItemSalesSetup(_salesLine.InventDimId).METSalesUnit;
                break;
            case METExtWMSUnit::DefaultPurchaseUnit:
                defaultUnit     = InventTable::find(_salesLine.ItemId).inventItemPurchSetup(_salesLine.InventDimId).METPurchUnit;
                break;
            default:
                break;
        }
        metPurchaseWMSFactor = this.getConversionFactor(_salesLine.SalesUnit, _salesLine.ItemId, _salesLine.InventDimId, defaultUnit);
    }

    if (!metPurchaseWMSFactor)
    {
        warning("@MET:NoUnitConvFound");
    }

    return metPurchaseWMSFactor;
}

/// <summary>
/// Get unit in ship case factor
/// </summary>
/// <param name = "_itemId">Item id for unit in ship case factor</param>
/// <param name = "_inventDimId">Inventdimid for unit in ship case factor</param>
/// <returns>Returns unit in ship case factor</returns>
public Factor getUnitinShipCaseFactor(ItemId _itemId, InventDimId _inventDimId)
{
    Factor                 shipCaseFactor;
    UnitOfMeasureSymbol    defaultUnit;
    METInventLocation      metInventLocation;
    InventLocation         inventLocation;

    select firstonly ExternalWMSUnit from metInventLocation
        exists join inventLocation
        where inventLocation.RecId == metInventLocation.InventLocation
        && inventLocation.inventlocationid == InventDim::find(_inventDimId).InventLocationId;

    switch (metInventLocation.ExternalWMSUnit)
    {
        case METExtWMSUnit::DefaultInventoryUnit:
            shipCaseFactor = 1;
            break;
        case METExtWMSUnit::DefaultSellUnit:
            defaultUnit     = InventTable::find(_itemId).inventItemSalesSetup(_inventDimId).METSalesUnit;
            break;
        case METExtWMSUnit::DefaultPurchaseUnit:
            defaultUnit     = InventTable::find(_itemId).inventItemPurchSetup(_inventDimId).METPurchUnit;
            break;
        default:
            break;
    }

    if (!shipCaseFactor)
    {
        shipCaseFactor = this.getConversionFactor(defaultUnit, _itemId, _inventDimId,  METConstants::unitEach);
    }

    return shipCaseFactor;
}
